142	namespace {
143	class GlobalHaltRequestedFinalizer {
144	public:
145	  GlobalHaltRequestedFinalizer(bool oneshot) : oneshot_(oneshot) {}
146	  ~GlobalHaltRequestedFinalizer()
147	  {
148	    if (!oneshot_) {
149	      global::globalHaltRequested = 5;
150	    }
151	  }
152	
153	private:
154	  bool oneshot_;
155	};
