187	void DownloadEngine::waitData()
188	{
189	  struct timeval tv;
190	  if (noWait_) {
191	    tv.tv_sec = tv.tv_usec = 0;
192	  }
193	  else {
194	    auto t =
195	        std::chrono::duration_cast<std::chrono::microseconds>(refreshInterval_);
196	    tv.tv_sec = t.count() / 1000000;
197	    tv.tv_usec = t.count() % 1000000;
198	  }
199	  eventPoll_->poll(tv);
200	}
