244	void DownloadEngine::afterEachIteration()
245	{
246	  if (global::globalHaltRequested == 1) {
247	    A2_LOG_NOTICE(_("Shutdown sequence commencing..."
248	                    " Press Ctrl-C again for emergency shutdown."));
249	    requestHalt();
250	    global::globalHaltRequested = 2;
251	    setNoWait(true);
252	    setRefreshInterval(std::chrono::milliseconds(0));
253	    return;
254	  }
255	
256	  if (global::globalHaltRequested == 3) {
257	    A2_LOG_NOTICE(_("Emergency shutdown sequence commencing..."));
258	    requestForceHalt();
259	    global::globalHaltRequested = 4;
260	    setNoWait(true);
261	    setRefreshInterval(std::chrono::milliseconds(0));
262	    return;
263	  }
264	}
