374	bool getPeerInfo(Endpoint& res, const std::shared_ptr<SocketCore>& socket)
375	{
376	  try {
377	    res = socket->getPeerInfo();
378	    return true;
379	  }
380	  catch (RecoverableException& e) {
381	    // socket->getPeerInfo() can fail if the socket has been
382	    // disconnected.
383	    A2_LOG_INFO_EX("Getting peer info failed. Pooling socket canceled.", e);
384	    return false;
385	  }
