389	void DownloadEngine::poolSocket(const std::shared_ptr<Request>& request,
390	                                const std::shared_ptr<Request>& proxyRequest,
391	                                const std::shared_ptr<SocketCore>& socket,
392	                                std::chrono::seconds timeout)
393	{
394	  if (proxyRequest) {
395	    // If proxy is defined, then pool socket with its hostname.
396	    poolSocket(request->getHost(), request->getPort(), proxyRequest->getHost(),
397	               proxyRequest->getPort(), socket, std::move(timeout));
398	    return;
399	  }
400	
401	  Endpoint peerInfo;
402	  if (getPeerInfo(peerInfo, socket)) {
403	    poolSocket(peerInfo.addr, peerInfo.port, A2STR::NIL, 0, socket,
404	               std::move(timeout));
405	  }
406	}
