615	bool DownloadEngine::validateToken(const std::string& token)
616	{
617	  using namespace util::security;
618	
619	  if (!option_->defined(PREF_RPC_SECRET)) {
620	    return true;
621	  }
622	
623	  if (!tokenHMAC_) {
624	    tokenHMAC_ = HMAC::createRandom();
625	    if (!tokenHMAC_) {
626	      A2_LOG_ERROR("Failed to create HMAC");
627	      return false;
628	    }
629	    tokenExpected_ = make_unique<HMACResult>(
630	        tokenHMAC_->getResult(option_->get(PREF_RPC_SECRET)));
631	  }
632	
633	  return *tokenExpected_ == tokenHMAC_->getResult(token);
634	}
