312	void DownloadEngine::evictSocketPool()
313	{
314	  if (socketPool_.empty()) {
315	    return;
316	  }
317	
318	  std::multimap<std::string, SocketPoolEntry> newPool;
319	  A2_LOG_DEBUG("Scanning SocketPool and erasing timed out entry.");
320	  for (auto& elem : socketPool_) {
321	    if (!elem.second.isTimeout()) {
322	      newPool.insert(elem);
323	    }
324	  }
325	  A2_LOG_DEBUG(
326	      fmt("%lu entries removed.",
327	          static_cast<unsigned long>(socketPool_.size() - newPool.size())));
328	  socketPool_ = std::move(newPool);
329	}
