448	std::shared_ptr<SocketCore>
449	DownloadEngine::popPooledSocket(const std::string& ipaddr, uint16_t port,
450	                                const std::string& proxyhost,
451	                                uint16_t proxyport)
452	{
453	  std::shared_ptr<SocketCore> s;
454	  auto i = findSocketPoolEntry(
455	      createSockPoolKey(ipaddr, port, A2STR::NIL, proxyhost, proxyport));
456	  if (i != socketPool_.end()) {
457	    s = (*i).second.getSocket();
458	    socketPool_.erase(i);
459	  }
460	  return s;
461	}
